use crate::{model::*,unit_support::*,jz42 as j};
fn setup(assets:usize,destroyed:usize)->(Game,String){let mut g=game();g.players[0].society_zone.card=Some(g.make_card("MSJC13",0));fund(&mut g,0,"JC049",assets);for r in 0..destroyed{g.regions[r].destroyed=true;}let id=held(&mut g,j::ID,0);(g,id)}
#[test]fn jz42_full_price_no_response_and_original_society_markers_preserved(){let(mut g,id)=setup(19,0);let c=g.players[0].society_zone.card.as_mut().unwrap();let old=c.id.clone();c.time_markers=0;c.damage=1;c.exhausted=true;g.players[0].society_zone.exposure=0;g.players[0].society_zone.secrecy=3;act(&mut g,0,Action{card_id:Some(id),..Action::new("play")});assert_eq!(g.pending.as_ref().unwrap().choice.kind,"jz42-time");restore(&mut g);choose(&mut g,vec![]);let c=g.players[0].society_zone.card.as_ref().unwrap();assert_eq!(c.definition,"MSJZ03");assert_ne!(c.id,old);assert_eq!((c.time_markers,c.damage,c.exhausted),(0,1,true));assert_eq!((g.players[0].society_zone.exposure,g.players[0].society_zone.secrecy),(0,3));assert!(g.stack.is_empty()&&g.pending.is_none());assert_eq!(g.resources(0),0);restore(&mut g);}
#[test]fn jz42_actual_destroyed_discount_and_optional_physical_time_payment(){let(mut g,id)=setup(5,3);let host=field(&mut g,"JC125",0);g.board_mut(&host).unwrap().time_markers=4;act(&mut g,0,Action{card_id:Some(id),..Action::new("play")});let ids=g.pending.as_ref().unwrap().choice.options[..2].iter().map(|o|o.id.clone()).collect();choose(&mut g,ids);assert_eq!(g.board(&host).unwrap().1.time_markers,2);assert_eq!(g.resources(0),0);assert!(g.msjz03_active(0));restore(&mut g);}
#[test]fn jz42_wrong_player_duplicate_time_and_corrupt_draft_rejected(){let(mut g,id)=setup(19,0);let host=field(&mut g,"JC125",0);g.board_mut(&host).unwrap().time_markers=2;act(&mut g,0,Action{card_id:Some(id),..Action::new("play")});let p=g.pending.clone().unwrap();reject(&mut g,1,Action{choice_id:Some(p.choice.id.clone()),selected:Some(vec![]),..Action::new("choose")});let opt=p.choice.options[0].id.clone();reject(&mut g,0,Action{choice_id:Some(p.choice.id),selected:Some(vec![opt.clone(),opt]),..Action::new("choose")});for n in 0..3{let mut x=g.clone();match n{0=>x.pending.as_mut().unwrap().seat=1,1=>x.pending.as_mut().unwrap().choice.options.clear(),_=>if let ChoiceResolution::JZ42Payment{draft}=&mut x.pending.as_mut().unwrap().resolution{draft.card.definition="JC001".into();}}assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err());let r=crate::room::RoomEnvelope::from_game(x);assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}}
#[test]fn jz42_original_closed_and_red_ring_project_nonasset(){let(mut g,id)=setup(19,0);reject(&mut g,0,Action{card_id:Some(id),..Action::new("asset")});let c=crate::catalog::card(j::ID);assert!(!c.supported);assert_eq!(c.loyalty.len(),5);assert_eq!(c.cost,19);assert!(crate::society::definition("MSJZ03").unwrap().unresolved_abilities.is_empty());assert!(!crate::society::definition("MSJZ03").unwrap().card.supported);assert_current_serial_catalog();crate::rules::validate_definitions(crate::rules::definitions()).unwrap();}
#[test]fn jz42_natural_conversion_clock_actions_and_bq047_export(){
 use crate::{deck,catalog,abi112_review_play_tests::Trace};
 fn start(seed:u64)->(Game,deck::DeckDraft){let mut d=deck::preset("watchers").unwrap();d.society_id=Some("MSCQ02".into());d.core_card_id=None;d.cards=vec![catalog::DeckEntry{card_id:"BQ047".into(),count:3},catalog::DeckEntry{card_id:"JZ42".into(),count:1},catalog::DeckEntry{card_id:"JC049".into(),count:3},catalog::DeckEntry{card_id:"JC042".into(),count:3},catalog::DeckEntry{card_id:"JC045".into(),count:3},catalog::DeckEntry{card_id:"JZ33".into(),count:3},catalog::DeckEntry{card_id:"JC043".into(),count:3},catalog::DeckEntry{card_id:"JC044".into(),count:3},catalog::DeckEntry{card_id:"JC046".into(),count:3},catalog::DeckEntry{card_id:"JC047".into(),count:3},catalog::DeckEntry{card_id:"JC048".into(),count:3},catalog::DeckEntry{card_id:"JC125".into(),count:19}];let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if ["BQ047","JZ42"].contains(&c.id.as_str()){c.supported=true;}}let mut ss=catalog::catalog().societies.clone();ss.iter_mut().find(|s|s.card.id=="MSCQ02").unwrap().card.supported=true;let d=deck::validate_with_registry(d,&cards,&ss).unwrap();let mut other=d.clone();other.society_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("doom".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}
 let(seed,g,d)=(1..8193).find_map(|seed|{let(g,d)=start(seed);let early=g.players[0].hand.iter().chain(g.players[0].deck.iter().take(7)).collect::<Vec<_>>();let bank=early.iter().filter(|c|catalog::card(&c.definition).color=="红"&&!matches!(c.definition.as_str(),"BQ047"|"JZ42")).count();(early.iter().filter(|c|c.definition=="BQ047").count()==3&&early.iter().any(|c|c.definition=="JZ42")&&bank>=5).then_some((seed,g,d))}).unwrap();let mut t=Trace::new_preserving_rng(g,"doom-natural-conversion-and-clock".into(),7420);let mut before=0;let mut after=false;let mut generated=false;let mut marked=false;let mut convert_step=None;let mut clock_branch=false;
 for step in 0..2600{
  if step%100==0{eprintln!("doom natural step={step} turn={} assets={} red={} before={before} converted={} generated={generated} after={after} marked={marked}",t.room.game.turn,t.room.game.players[0].assets.len(),t.room.game.players[0].assets.iter().filter(|c|catalog::card(&c.definition).color=="红").count(),t.room.game.msjz03_active(0));}
  if let Some(p)=t.room.game.pending.clone(){if matches!(p.resolution,ChoiceResolution::Forecast{..}|ChoiceResolution::Frame{choice:FrameChoice::Forecast{..},..}){t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(p.choice.options.iter().map(|o|o.id.clone()).collect()),bottom:Some(vec![]),..Action::new("choose")});continue}if p.choice.kind=="bq047-assets"{clock_branch=true;}let min=p.choice.min.unwrap_or(0);let mut opts=p.choice.options.clone();if p.choice.kind.contains("discard"){opts.sort_by_key(|o|t.room.game.players[p.seat].hand.iter().find(|c|c.id==o.id).map_or(0,|c|match c.definition.as_str(){"JC125"=>0,"BQ047"=>3,"JZ42"=>4,_=>1}));}let ids=if p.choice.kind=="trigger"{p.choice.options.iter().filter(|o|o.id=="accept").map(|o|o.id.clone()).collect()}else{opts.iter().take(min).map(|o|o.id.clone()).collect()};t.choose(ids);continue}
  if after&&generated&&marked&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break}
  let g=&t.room.game;assert_eq!(g.status,"playing","natural ended at {step}");let legal=g.legal_actions(0);let card_is=|a:&&crate::model::LegalAction,id:&str|g.players[0].hand.iter().any(|c|Some(&c.id)==a.action.card_id.as_ref()&&c.definition==id);
  let wanted=if (g.players[0].assets.len()<7||!g.loyalty(0,"JZ42"))&&!g.msjz03_active(0){legal.iter().find(|a|a.action.kind=="asset"&&g.players[0].hand.iter().find(|c|Some(&c.id)==a.action.card_id.as_ref()).is_some_and(|c|if !g.loyalty(0,"JZ42"){catalog::card(&c.definition).color=="红"&&!matches!(c.definition.as_str(),"BQ047"|"JZ42")}else{!matches!(c.definition.as_str(),"BQ047"|"JZ42")}))}
   else if before<2{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.region==Some(before)&&card_is(a,"BQ047"))}
   else if !g.msjz03_active(0){legal.iter().find(|a|a.action.kind=="play"&&card_is(a,"JZ42"))}
   else if !generated{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::msjz03::GENERATE)&&a.action.region==Some(0)&&a.action.cost_selected.as_ref().is_some_and(|ids|ids.iter().all(|id|g.players[0].hand.iter().any(|c|&c.id==id&&!matches!(c.definition.as_str(),"BQ047"|"JZ42")))))}
   else if !after{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.region==Some(0)&&card_is(a,"BQ047"))}
   else if !marked{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::msjz03::ADD)&&a.action.option.as_deref()==Some("carrier")&&a.action.target_id.as_ref().is_some_and(|id|g.board(id).is_some_and(|(_,c)|c.definition=="TK009")))}else{None};
  if let Some(a)=wanted{let a=a.action.clone();if a.kind=="deploy"{if before<2{before+=1}else{after=true}}if a.kind=="play"{convert_step=Some(step);}if a.ability_id.as_deref()==Some(crate::msjz03::GENERATE){generated=true;}if a.ability_id.as_deref()==Some(crate::msjz03::ADD){marked=true;}t.action(0,a);}else{t.pass();}
 }
 assert!(before==2&&after&&generated&&marked&&clock_branch,"before={before} after={after} generated={generated} marked={marked} branch={clock_branch}");assert!(t.room.game.msjz03_active(0));assert!(t.room.game.regions[0].cards.iter().any(|c|c.definition=="TK009"&&c.time_markers>=1));
 let mut v=t.value();v["catalog"]=serde_json::to_value(catalog::catalog()).unwrap();v["sourceBindings"]=doom_bindings();v["construction"]=serde_json::json!({"deck":d,"seed":seed,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true,"conversionDeclarationStep":convert_step});for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let duplicate=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(duplicate.state,s["expected"]["state"]);assert!(!duplicate.changed&&duplicate.journal.is_empty());s["duplicate"]=serde_json::to_value(duplicate).unwrap();}if let Ok(p)=std::env::var("DOOM_NATURAL_OUT"){std::fs::write(p,serde_json::to_vec(&v).unwrap()).unwrap();}
}

fn doom_bindings()->serde_json::Value{use sha2::{Digest,Sha256};let mut b=crate::shoggoth_tests::shoggoth_source_bindings();for(n,s)in[("rust-game/src/jz42.rs",include_bytes!("jz42.rs").as_slice()),("rust-game/src/jz42_tests.rs",include_bytes!("jz42_tests.rs").as_slice()),("rust-game/src/msjz03.rs",include_bytes!("msjz03.rs").as_slice()),("rust-game/src/msjz03_tests.rs",include_bytes!("msjz03_tests.rs").as_slice()),("rust-game/src/generated.rs",include_bytes!("generated.rs").as_slice()),("rust-game/src/death_observers.rs",include_bytes!("death_observers.rs").as_slice()),("rust-game/src/region_destruction.rs",include_bytes!("region_destruction.rs").as_slice())]{b["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(s)));}b}
#[test]fn jz42_replacement_keeps_queued_original_society_response_without_identity_collision(){let(mut g,id)=setup(19,0);g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));g.players[0].society_zone.loss_control=1;let old=g.players[0].society_zone.card.as_ref().unwrap().id.clone();let c=g.make_card("BQ046",0);let core=c.id.clone();g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:"BQ046".into(),rest:0,card:Some(c)});act(&mut g,0,Action{card_id:Some(id),..Action::new("play")});choose(&mut g,vec![]);assert!(g.msjz03_active(0));assert_eq!(g.core_zones[0].card.as_ref().unwrap().id,core);assert!(g.stack.iter().any(|s|s.frame.as_ref().is_some_and(|f|f.source.card.id==old&&f.source.card.definition=="MSBQ02")));restore(&mut g);while !g.stack.is_empty(){top(&mut g);}assert_eq!(g.players[0].society_zone.loss_control,1,"a paid observation bound to the departed society cannot move its target to the replacement");restore(&mut g);}
